package org.trillionnium.hepta.local;
import android.content.Context;import android.os.SystemClock;import android.system.Os;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.lang.reflect.Field;import java.util.*;import org.json.*;import org.trillionnium.hepta.webprotocol.*;import org.trillionnium.hepta.webhelper.*;
/** Actual Client/Journal/Receipt/Files plus exact Session method blocks.
 * OS UID/PM/Binder/WebView callback boundaries are synthetic; file bytes/modes/link operations are real Linux.
 * No Android/phone/physical directory fsync or business success is claimed. */
public final class CaptureAckHostTest {
 interface Checked {void run()throws Exception;}static int cases,assertions,serial;static final ArrayList<String> names=new ArrayList<String>();static Path root;
 static void need(boolean b,String why){assertions++;if(!b)throw new AssertionError(why);}
 static void test(String n,Checked t)throws Exception{Os.resetFaults();t.run();cases++;names.add(n);}
 static void rejects(Checked t)throws Exception{boolean failed=false;try{t.run();}catch(Exception e){failed=true;}need(failed,"must fail closed");}
 static String rep(char c,int n){char[] a=new char[n];Arrays.fill(a,c);return new String(a);}
 static JSONObject copy(JSONObject o)throws Exception{return new JSONObject(o.toString());}
 static byte[] bytes(Path p)throws Exception{return Files.readAllBytes(p);}
 static void overwrite(Path p,byte[] b)throws Exception{Files.write(p,b,StandardOpenOption.TRUNCATE_EXISTING);}
 static void privateWrite(Path p,byte[] b)throws Exception{Files.write(p,b,StandardOpenOption.CREATE_NEW);Files.setAttribute(p,"unix:mode",0600);}
 static JSONObject read(Path p)throws Exception{return new JSONObject(new String(bytes(p),StandardCharsets.UTF_8));}
 static final class Env implements AutoCloseable {
  final JSONObject binding;final Path main,helper;final Context context;final WebEvidenceJournal journal;final HelperFilesAccess files;HelperPeer peer;WebEvidenceClient client;
  Env()throws Exception{android.os.Process.fixtureUid(10481);SystemClock.now=1000;Path dir=root.resolve("case-"+(++serial));Files.createDirectory(dir);main=dir.resolve("main");helper=dir.resolve("helper");Files.createDirectory(main);Files.createDirectory(helper);Os.fixtureUidRoot(main.toString(),10481);Os.fixtureUidRoot(helper.toString(),10484);binding=HostCaptureFixture.binding();context=new Context(main.toFile());Path evidence=main.resolve("control-tasks").resolve(binding.getString("task_id"));Files.createDirectories(evidence);journal=WebEvidenceJournal.create(context,new QualificationScopeConfig.FilesRoot(context),evidence.toFile(),binding);files=new HelperFilesAccess(helper.toFile(),binding);}
  void connect()throws Exception{peer=new HelperPeer(new Context(helper.toFile()),binding);context.fixturePeer=peer;client=new WebEvidenceClient(context,new WebHelperIdentity(binding.getJSONObject("controller_identity")),new WebHelperIdentity(binding.getJSONObject("helper_identity")),binding,new WebEvidenceClient.Guard(){public void requireCurrent(boolean cleanup){}public boolean cancelled(){return false;}},journal);client.connect(9000);client.attach(client.newAttach(9000));}
  public void close()throws Exception{if(client!=null)client.close();if(peer!=null)peer.close();android.os.Process.fixtureUid(10481);Os.resetFaults();}
 }
 static final class Prepared {
  final Env env;final String nonce=rep('c',64);final JSONObject request,record,callback;final byte[] raw;final WebEvidenceReceipt verified;JSONObject proof,ack;String wire;
  Prepared(Env e)throws Exception{env=e;request=new JSONObject().put("schema",WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.CAPTURE)).put("task_id",e.binding.get("task_id")).put("controller_session_nonce",e.binding.get("controller_session_nonce")).put("request_nonce",nonce).put("deadline_elapsed_ms",9000L).put("expected_webview_instance",HostCaptureFixture.INSTANCE).put("expected_navigation_epoch",7);
   record=HostCaptureFixture.envelope(e.binding,request);raw=e.files.store(nonce,record);callback=HostCaptureFixture.callback(WebEvidenceProtocol.CAPTURE,request,e.binding,"captured",raw);
   verified=WebEvidenceReceipt.verify(WebEvidenceProtocol.CAPTURE,request.toString(),e.binding,callback.toString(),raw,10484,1000,SystemClock.now);
   e.journal.request(WebEvidenceProtocol.CAPTURE,nonce,request.toString());e.journal.response(WebEvidenceProtocol.CAPTURE,nonce,callback.toString(),raw,true);
  }
  Path path(String prefix){return env.journal.directory.toPath().resolve(prefix+"-"+nonce+".json");}
  void prepare()throws Exception{proof=env.journal.captureAcknowledgement(nonce,verified);ack=new JSONObject().put("schema",WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.ACK_CAPTURE)).put("task_id",env.binding.get("task_id")).put("controller_session_nonce",env.binding.get("controller_session_nonce")).put("request_nonce",rep('d',64)).put("deadline_elapsed_ms",9000L).put("capture_request_nonce",nonce).put("durable_acknowledgement",proof).put("durable_acknowledgement_sha256",WebDomCanonical.sha256(proof));wire=ack.toString();env.files.durable(ack,wire);}
  Path helperRaw(){return env.files.capturePath(nonce).toPath();}
  void send()throws Exception{env.files.ack(ack,wire,true);}
  void proofMutation(String key,Object value)throws Exception{proof.put(key,value);ack.put("durable_acknowledgement_sha256",WebDomCanonical.sha256(proof));wire=ack.toString();env.files.durable(ack,wire);}
 }
 public static void main(String[] args)throws Exception{
  if(args.length!=2)throw new IllegalArgumentException("report/root");root=Paths.get(args[1]);Files.createDirectory(root);
  test("actual_capture_persist_ack_arm_navigation_and_following_capture",()->{try(Env e=new Env()){e.connect();WebEvidenceReceipt first=e.client.capture(9000);need("captured".equals(first.status),"first capture");String n=first.callback().getString("request_nonce");need(!Files.exists(e.files.capturePath(n).toPath()),"exact helper copy retired");need(Files.exists(e.journal.directory.toPath().resolve("raw-"+n+".json"))&&Files.exists(e.journal.directory.toPath().resolve("transfer-"+n+".json")),"controller copies persist");need(e.peer.session.hasLastSuccessful(),"ACK leaves helper capability");
   WebEvidenceReceipt arm=e.client.armObservedLink(first,HostCaptureFixture.ANCHOR,rep('e',32),9000);need("armed".equals(arm.status)&&arm.arm()!=null,"same-lease actual ARM path");need(!e.peer.session.hasLastSuccessful(),"ARM itself consumes helper source");need(!Files.exists(e.files.capturePath(n).toPath()),"ARM did not reopen/recreate deleted capture");e.peer.clickAndCommit();
   WebEvidenceReceipt changed=e.client.capture(9000);need("state_changed".equals(changed.status),"navigation observed as new epoch");WebEvidenceReceipt second=e.client.capture(9000);need("captured".equals(second.status)&&second.epoch>first.epoch&&second.capture().getJSONObject("observed_link_navigation").getBoolean("same_lease_main_load_returned"),"new capture verifies actual permit callback chain");
   need(!Files.exists(e.files.capturePath(second.callback().getString("request_nonce")).toPath()),"second exact ACK");rejects(()->e.client.armObservedLink(first,HostCaptureFixture.ANCHOR,rep('f',32),9000));need(e.peer.session.usedCount()==7,"attach + 2 successful captures/ACKs + ARM + state-change");}});
  test("helper_deletes_only_exact_formal_capture_after_durable_main_readback",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Path keep=e.files.root().toPath().resolve("diagnostic-keep.json");privateWrite(keep,"{\"keep\":true}".getBytes(StandardCharsets.UTF_8));byte[] journal=bytes(e.files.root().toPath().resolve("lease-journal.json"));p.send();need(!Files.exists(p.helperRaw()),"removed exact leaf");need(Files.exists(keep)&&Arrays.equals(journal,bytes(e.files.root().toPath().resolve("lease-journal.json"))),"journal/diagnostic retained");need(Arrays.equals(p.raw,bytes(p.path("raw"))),"durable main original retained");}});
  for(String prefix:new String[]{"request","reply","raw"})test("missing_main_"+prefix+"_prevents_transfer",()->{try(Env e=new Env()){Prepared p=new Prepared(e);Files.delete(p.path(prefix));rejects(()->p.prepare());need(Files.exists(p.helperRaw()),"helper raw retained");}});
  for(String prefix:new String[]{"request","reply","raw"})test("modified_main_"+prefix+"_prevents_transfer",()->{try(Env e=new Env()){Prepared p=new Prepared(e);byte[] b=bytes(p.path(prefix));b[b.length-2]=(byte)'!';overwrite(p.path(prefix),b);rejects(()->p.prepare());need(Files.exists(p.helperRaw()),"helper raw retained");}});
  test("unverified_main_reply_never_acknowledged",()->{try(Env e=new Env()){Prepared p=new Prepared(e);JSONObject reply=read(p.path("reply")).put("callback_verification_passed",false);overwrite(p.path("reply"),reply.toString().getBytes(StandardCharsets.UTF_8));rejects(()->p.prepare());need(Files.exists(p.helperRaw()),"retained");}});
  test("main_transfer_proof_create_only",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();rejects(()->e.journal.captureAcknowledgement(p.nonce,p.verified));need(Files.exists(p.helperRaw()),"no deletion by proof replay");}});
  test("no_helper_durable_consumed_ACK_no_deletion",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Files.delete(e.files.root().toPath().resolve("lease-journal.json"));rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  for(String key:new String[]{"binding_sha256","state","consumed_requests"})test("helper_journal_"+key+"_mismatch_rejected",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Path j=e.files.root().toPath().resolve("lease-journal.json");JSONObject changed=read(j).put(key,key.equals("consumed_requests")?new JSONObject():key.equals("state")?"closed":rep('0',64));overwrite(j,changed.toString().getBytes(StandardCharsets.UTF_8));rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  for(String suffix:new String[]{".new",".bak"})test("helper_journal_unfinished_"+suffix+"_rejected",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();privateWrite(e.files.root().toPath().resolve("lease-journal.json"+suffix),new byte[]{1});rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  for(String key:new String[]{"task_id","controller_session_nonce","binding_sha256","raw_sha256","raw_bytes","capture_request_sha256","raw_file","business_verified","grants_page_authority","durable_copy_readback_verified"})test("proof_"+key+"_negative",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Object value=key.equals("raw_bytes")?p.raw.length+1:key.equals("task_id")?rep('0',32):key.equals("raw_file")?"../lease-journal.json":key.equals("business_verified")||key.equals("grants_page_authority")?true:key.equals("durable_copy_readback_verified")?false:rep('0',64);p.proofMutation(key,value);rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  test("same_capture_ack_nonce_is_rejected",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();p.ack.put("request_nonce",p.nonce);p.wire=p.ack.toString();e.files.durable(p.ack,p.wire);rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  test("exact_wire_hash_not_reserialized_object_required",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();String pretty=p.ack.toString(2);rejects(()->e.files.ack(p.ack,pretty,true));need(Files.exists(p.helperRaw()),"wrong consumed wire retained");}});
  test("capture_symlink_target_is_not_deleted",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Path outside=e.helper.resolve("external-copy.json");Files.move(p.helperRaw(),outside);Files.createSymbolicLink(p.helperRaw(),outside);rejects(()->p.send());need(Files.exists(outside)&&Files.isSymbolicLink(p.helperRaw()),"outside and symlink retained");}});
  test("capture_hardlink_is_not_deleted",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Path other=e.helper.resolve("hard-copy.json");Files.createLink(other,p.helperRaw());rejects(()->p.send());need(Files.exists(other)&&Files.exists(p.helperRaw()),"both links retained");}});
  test("capture_nonprivate_mode_is_not_deleted",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Files.setAttribute(p.helperRaw(),"unix:mode",0644);rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  test("stale_lease_guard_prevents_deletion",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();rejects(()->e.files.ack(p.ack,p.wire,false));need(Files.exists(p.helperRaw()),"retained");}});
  test("journal_fsync_failure_before_unlink_retains_capture",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Os.resetFaults();Os.failFsyncPath=e.files.root()+"/lease-journal.json";rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  test("parent_presync_failure_retains_capture",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Os.resetFaults();Os.failFsyncPath=e.files.root().toString();rejects(()->p.send());need(Files.exists(p.helperRaw()),"retained");}});
  test("post_unlink_parent_sync_failure_is_non_success_with_main_copy",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();Os.resetFaults();Os.failFsyncPath=e.files.root().toString();Os.failFsyncOccurrence=2;rejects(()->p.send());need(!Files.exists(p.helperRaw()),"unlink actually happened before injected failure");need(Arrays.equals(p.raw,bytes(p.path("raw"))),"main durable copy preserved");}});
  test("duplicate_ack_does_not_claim_second_success",()->{try(Env e=new Env()){Prepared p=new Prepared(e);p.prepare();p.send();rejects(()->p.send());need(Arrays.equals(p.raw,bytes(p.path("raw"))),"main original retained");}});
  test("actual_client_main_raw_fsync_failure_sends_no_ACK",()->{try(Env e=new Env()){e.connect();Os.failFsyncLeafPrefix="raw-";rejects(()->e.client.capture(9000));need(e.peer.session.methods.size()==2&&!e.peer.session.methods.contains(WebEvidenceProtocol.ACK_CAPTURE),"only attach/capture dispatched");need(e.peer.session.root().list((d,n)->n.startsWith("capture-")).length==1,"helper original retained");}});
  test("actual_client_ACK_preserves_original128_budget",()->{try(Env e=new Env()){e.connect();Field used=WebEvidenceClient.class.getDeclaredField("used");used.setAccessible(true);used.setInt(e.client,127);rejects(()->e.client.capture(9000));need(!e.peer.session.methods.contains(WebEvidenceProtocol.ACK_CAPTURE),"ACK did not bypass count");need(e.peer.session.root().list((d,n)->n.startsWith("capture-")).length==1,"helper retained after exhausted budget");}});
  test("actual_helper_128_consumed_budget_is_not_extended",()->{try(Env e=new Env()){e.connect();int old=android.os.Process.myUid();android.os.Process.fixtureUid(10484);try{e.peer.session.fixtureConsumed(128);}finally{android.os.Process.fixtureUid(old);}rejects(()->e.client.capture(9000));need(e.peer.session.root().list((d,n)->n.startsWith("capture-")).length==0,"no capture effect after budget");}});
  JSONObject result=new JSONObject().put("all_pass",true).put("cases",cases).put("assertions",assertions).put("names",new JSONArray(names)).put("actual_production_client_journal_receipt_files",true).put("exact_session_method_projection",true).put("android_runtime_execution",false).put("binder_uid_and_webview_boundaries_synthetic",true).put("physical_android_fsync_verified",false).put("phone_operations",0).put("business_verified",false);
  Files.write(Paths.get(args[0]),(result.toString(2)+"\n").getBytes(StandardCharsets.UTF_8),StandardOpenOption.CREATE_NEW);System.out.println(cases+" cases / "+assertions+" assertions");
 }
}
